    int8_t move_y = (int8_t)rx_buf[2]; // Trượt ngang (-100..100)
}

# LỆNH HỎI DỮ LIỆU TỪ HOST (115200 bps):
TX -> "?IO,ALL
"

# PHẢN HỒI TỪ BOARD INPUT-F4-IO:
RX <- "!IO,D:0x00A4,L1:425,L2:310,L3:890,L4:120
"
// Giải thích:
// - D:0x00A4 : Bitmask 16 ngõ vào số (kênh nào có vật cản = 1)
// - L1..L4   : Khoảng cách đọc từ 4 cảm biến Laser (đơn vị: mm)

// Bật chế độ xuất dữ liệu thí nghiệm 50Hz:
$LOG,ON

// Dữ liệu nhận được để vẽ đồ thị trong báo cáo:
// "DATA,t_ms,X_set,X_real,Y_set,Y_real,Yaw_deg,RPM1,RPM2,RPM3,RPM4"

$PID,12.5,0.4,1.8
   // Đặt Kp=12.5, Ki=0.4, Kd=1.8
